Script:
Invoices = { 
    invoiceTypes: [
        { id: 1, name: "[resource_displayname[SalesInvoice]]" },
        { id: 2, name: "[resource_displayname[CopyInvoice]]" },
        { id: 3, name: "[resource_displayname[Replacement]]" },
        { id: 4, name: "[resource_displayname[SelfBillingInvoice]]" },
        { id: 5, name: "[resource_displayname[ProFormaInv]]" }
    ],
        states: [script[TransactionStates]],

    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=Invoices]");
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[B2B/Invoice]]
                ]
            }
        ]);
        var dataSource = await model.getDatasource({ endpoint: "B2B/Invoice", odataAppend: "/FromSystem(SystemId='" + session.app.Config.B2B.TransactionSource + "')?$expand=Companies" });
        (await [script[InvoiceGrid]]({element: container, dataSource: dataSource})).init();
    } 
};
